/* From Uiverse.io by Mizohack  - Tags: card */
.__UIV_SCOPE__ .wrapper {
  height: 100px;
  width: 240px;
  position: relative;
  background: linear-gradient(135deg, #14ffe9, #ffeb3b, #ff00e0);
  border-radius: 10px;
  cursor: default;
  animation: animate 1.5s linear infinite;
}
.__UIV_SCOPE__ .wrapper .display,
.__UIV_SCOPE__ .wrapper span {
  position: absolute;
  top: 50%;
  left: 50%;
  transform: translate(-50%, -50%);
}
.__UIV_SCOPE__ .wrapper .display {
  z-index: 999;
  height: 85px;
  width: calc(100% - 16px);
  background: #1b1b1b;
  border-radius: 6px;
  text-align: center;
}
.__UIV_SCOPE__ .display #time {
  line-height: 85px;
  color: #fff;
  font-size: 50px;
  font-weight: 600;
  letter-spacing: 1px;
  background: linear-gradient(135deg, #14ffe9, #ffeb3b, #ff00e0);
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
  animation: animate 1.5s linear infinite;
}
@keyframes animate {
  100% {
    filter: hue-rotate(360deg);
  }
}
.__UIV_SCOPE__ .wrapper span {
  height: 100%;
  width: 100%;
  border-radius: 10px;
  background: inherit;
}
.__UIV_SCOPE__ .wrapper span:first-child {
  filter: blur(7px);
}
.__UIV_SCOPE__ .wrapper span:last-child {
  filter: blur(20px);
}
